mapper.select:
SELECT teacherid, teacherno, teachername, sex, phone, email, title, department, createtime, avatar FROM teacher
AND (teacherno LIKE CONCAT('%', #{keyword}, '%') OR teachername LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY teacherid LIMIT #{offset}, #{limit}

SELECT teacherid, teacherno, teachername, sex, phone, email, title, department, createtime, avatar
FROM teacher
WHERE teacherid = #{teacherid}

SELECT teacherid, teacherno, teachername, password, sex, phone, email, title, department, createtime, avatar
FROM teacher
WHERE teacherid = #{teacherid}

SELECT teacherid, teacherno, teachername, password, sex, phone, email, title, department, createtime, avatar
FROM teacher
WHERE teacherno = #{teacherno}

mapper.update:
UPDATE teacher
SET teacherno = #{teacherno}, teachername = #{teachername}, password = #{password}, sex = #{sex},
    phone = #{phone}, email = #{email}, title = #{title}, department = #{department}, avatar = #{avatar}
WHERE teacherid = #{teacherid}
